import React from "react";
import styled from "styled-components";
import { useAppContext, actions } from "../context/AppContext";

const ControlsContainer = styled.div`
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 10px;
  z-index: 100;
`;

const ControlButton = styled.button`
  background-color: rgba(42, 42, 42, 0.9);
  color: white;
  border: none;
  padding: 12px 20px;
  border-radius: 8px;
  cursor: pointer;
  font-family: "League Spartan", sans-serif;
  font-size: 14px;
  font-weight: 600;
  transition: all 0.3s ease;

  &:hover {
    background-color: rgba(66, 66, 66, 0.9);
    transform: translateY(-2px);
  }

  &:active {
    transform: translateY(0);
  }

  &.active {
    background-color: rgba(255, 71, 87, 0.9);
  }
`;

const StatusText = styled.div`
  color: white;
  font-size: 12px;
  text-align: center;
  margin-top: 5px;
  background: rgba(0, 0, 0, 0.7);
  padding: 4px 8px;
  border-radius: 4px;
`;

export default function AnimationControls({ startAutoAnimation, stopAutoAnimation }) {
  const { state } = useAppContext();

  const isAutoAnimating = state.animation.isAutoAnimating;
  const currentCountryIndex = state.animation.currentCountryIndex;

  return (
    <ControlsContainer>
      <div>
        <ControlButton
          className={isAutoAnimating ? "active" : ""}
          onClick={isAutoAnimating ? stopAutoAnimation : startAutoAnimation}
        >
          {isAutoAnimating ? "Stop Animation" : "Start Animation"}
        </ControlButton>
        <StatusText>
          {isAutoAnimating ? `Country ${currentCountryIndex + 1}/10` : "Ready to animate"}
        </StatusText>
      </div>
    </ControlsContainer>
  );
}
